Here is the commit message:
smb: client: avoid double-free in smbd_free_send_io() after
 smbd_send_batch_flush()

smbd_send_batch_flush() already calls smbd_free_send_io(),
so we should not call it again after smbd_post_send()
moved it to the batch list.

Reported-by: Ruikai Peng <ruikai@pwno.io>
Closes: https://lore.kernel.org/linux-cifs/CAFD3drNOSJ05y3A+jNXSDxW-2w09KHQ0DivhxQ_pcc7immVVOQ@mail.gmail.com/
Fixes: 21538121efe6 ("smb: client: make use of smbdirect_socket.send_io.bcredits")
Cc: stable@kernel.org
Cc: Steve French <smfrench@gmail.com>
Cc: Tom Talpey <tom@talpey.com>
Cc: Long Li <longli@microsoft.com>
Cc: Ruikai Peng <ruikai@pwno.io>
Cc: Sergey Senozhatsky <senozhatsky@chromium.org>
Cc: linux-cifs@vger.kernel.org
Cc: samba-technical@lists.samba.org
Cc: security@kernel.org
Acked-by: Paulo Alcantara (Red Hat) <pc@manguebit.org>
Acked-by: Namjae Jeon <linkinjeon@kernel.org>
Signed-off-by: Stefan Metzmacher <metze@samba.org>
Tested-by: Ruikai Peng <ruikai@pwno.io>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
The function `smbd_post_send_iter()` in `smbdirect.c` has a bug in its error handling. When `smbd_post_send()` succeeds, it moves the `request` into a batch list. Then `smbd_send_batch_flush()` is called, which internally calls `smbd_free_send_io()` to free the request. However, if `smbd_send_batch_flush()` fails, the code previously fell through to the `err_dma` label, which calls `smbd_free_send_io()` again, causing a double-free. The patch adds a new label `err_flush` to skip the redundant `smbd_free_send_io()` call when the request has already been freed by `smbd_send_batch_flush()`.

Here is the patch:

 static int smbd_post_send_iter(struct smbdirect_socket *sc,
 			       struct smbdirect_send_batch *batch,
 			       struct iov_iter *iter,
 			       int *_remaining_data_length)
 {
 	struct smbdirect_socket_parameters *sp = &sc->parameters;
 	int rc;
 	int header_length;
 	int data_length;
 	struct smbdirect_send_io *request;
 	struct smbdirect_data_transfer *packet;
 	int new_credits = 0;
 	struct smbdirect_send_batch _batch;

 	if (!batch) {
 		smbd_send_batch_init(&_batch, false, 0);
 		batch = &_batch;
 	}

 	rc = wait_for_send_bcredit(sc, batch);
 	if (rc) {
 		log_outgoing(ERR, "disconnected not sending on wait_bcredit\n");
 		rc = -EAGAIN;
 		goto err_wait_bcredit;
 	}

 	rc = wait_for_send_lcredit(sc, batch);
 	if (rc) {
 		log_outgoing(ERR, "disconnected not sending on wait_lcredit\n");
 		rc = -EAGAIN;
 		goto err_wait_lcredit;
 	}

 	rc = wait_for_send_credits(sc, batch);
 	if (rc) {
 		log_outgoing(ERR, "disconnected not sending on wait_credit\n");
 		rc = -EAGAIN;
 		goto err_wait_credit;
 	}

 	new_credits = manage_credits_prior_sending(sc);
 	if (new_credits == 0 &&
 	    atomic_read(&sc->send_io.credits.count) == 0 &&
 	    atomic_read(&sc->recv_io.credits.count) == 0) {
 		queue_work(sc->workqueue, &sc->recv_io.posted.refill_work);
 		rc = wait_event_interruptible(sc->send_io.credits.wait_queue,
 					      atomic_read(&sc->send_io.credits.count) >= 1 ||
 					      atomic_read(&sc->recv_io.credits.available) >= 1 ||
 					      sc->status != SMBDIRECT_SOCKET_CONNECTED);
 		if (sc->status != SMBDIRECT_SOCKET_CONNECTED)
 			rc = -ENOTCONN;
 		if (rc < 0) {
 			log_outgoing(ERR, "disconnected not sending on last credit\n");
 			rc = -EAGAIN;
 			goto err_wait_credit;
 		}

 		new_credits = manage_credits_prior_sending(sc);
 	}

 	request = smbd_alloc_send_io(sc);
 	if (IS_ERR(request)) {
 		rc = PTR_ERR(request);
 		goto err_alloc;
 	}

 	memset(request->sge, 0, sizeof(request->sge));

 	/* Map the packet to DMA */
 	header_length = sizeof(struct smbdirect_data_transfer);
 	/* If this is a packet without payload, don't send padding */
 	if (!iter)
 		header_length = offsetof(struct smbdirect_data_transfer, padding);

 	packet = smbdirect_send_io_payload(request);
 	request->sge[0].addr = ib_dma_map_single(sc->ib.dev,
 						 (void *)packet,
 						 header_length,
 						 DMA_TO_DEVICE);
 	if (ib_dma_mapping_error(sc->ib.dev, request->sge[0].addr)) {
 		rc = -EIO;
 		goto err_dma;
 	}

 	request->sge[0].length = header_length;
 	request->sge[0].lkey = sc->ib.pd->local_dma_lkey;
 	request->num_sge = 1;

 	/* Fill in the data payload to find out how much data we can add */
 	if (iter) {
 		struct smb_extract_to_rdma extract = {
 			.nr_sge		= request->num_sge,
 			.max_sge	= SMBDIRECT_SEND_IO_MAX_SGE,
 			.sge		= request->sge,
 			.device		= sc->ib.dev,
 			.local_dma_lkey	= sc->ib.pd->local_dma_lkey,
 			.direction	= DMA_TO_DEVICE,
 		};
 		size_t payload_len = umin(*_remaining_data_length,
 					  sp->max_send_size - sizeof(*packet));

 		rc = smb_extract_iter_to_rdma(iter, payload_len,
 					      &extract);
 		if (rc < 0)
 			goto err_dma;
 		data_length = rc;
 		request->num_sge = extract.nr_sge;
 		*_remaining_data_length -= data_length;
 	} else {
 		data_length = 0;
 	}

 	/* Fill in the packet header */
 	packet->credits_requested = cpu_to_le16(sp->send_credit_target);
 	packet->credits_granted = cpu_to_le16(new_credits);

 	packet->flags = 0;
 	if (manage_keep_alive_before_sending(sc))
 		packet->flags |= cpu_to_le16(SMBDIRECT_FLAG_RESPONSE_REQUESTED);

 	packet->reserved = 0;
 	if (!data_length)
 		packet->data_offset = 0;
 	else
 		packet->data_offset = cpu_to_le32(24);
 	packet->data_length = cpu_to_le32(data_length);
 	packet->remaining_data_length = cpu_to_le32(*_remaining_data_length);
 	packet->padding = 0;

 	log_outgoing(INFO, "credits_requested=%d credits_granted=%d data_offset=%d data_length=%d remaining_data_length=%d\n",
 		     le16_to_cpu(packet->credits_requested),
 		     le16_to_cpu(packet->credits_granted),
 		     le32_to_cpu(packet->data_offset),
 		     le32_to_cpu(packet->data_length),
 		     le32_to_cpu(packet->remaining_data_length));

 	rc = smbd_post_send(sc, batch, request);
 	if (!rc) {
+		/*
+		 * From here request is moved to batch
+		 * and we should not free it explicitly.
+		 */
+
 		if (batch != &_batch)
 			return 0;

 		rc = smbd_send_batch_flush(sc, batch, true);
 		if (!rc)
 			return 0;
+
+		goto err_flush;
 	}

 err_dma:
 	smbd_free_send_io(request);

+err_flush:
 err_alloc:
 	atomic_inc(&sc->send_io.credits.count);
 	wake_up(&sc->send_io.credits.wait_queue);

 err_wait_credit:
 	atomic_inc(&sc->send_io.lcredits.count);
 	wake_up(&sc->send_io.lcredits.wait_queue);

 err_wait_lcredit:
 	atomic_add(batch->credit, &sc->send_io.bcredits.count);
 	batch->credit = 0;
 	wake_up(&sc->send_io.bcredits.wait_queue);

 err_wait_bcredit:
 	return rc;
 }



